def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            todo = [(r, c)]
            seen.add((r, c))
            component = []
            touches_edge = False
            while todo:
                y, x = todo.pop()
                component.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            grid[yy][xx] == bg and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        todo.append((yy, xx))
            if not touches_edge:
                for y, x in component:
                    out[y][x] = 4
    return out
